from ordering import key
def page(records, cursor=None, limit=2):
    if limit <= 0:
        raise ValueError('Nonpositive limit')
    ordered = sorted(records, key=key)
    if cursor is not None:
        ordered = [r for r in ordered if r['id'] > cursor[1]]
    items = ordered[:limit]
    return items, ((items[-1]['score'],items[-1]['id']) if items else None)
